descriptor.controllerScript:
/*
 * LAB 4 - WIDGET "Lab4 - Tiêu đề & điều hướng" (NT532.R12 - Nhóm 10)
 *
 * Widget tĩnh (static) đặt ở đầu MỌI state của dashboard:
 * - Hiện tiêu đề "NT532.R12 - Nhóm 10 · Lab 4", mô tả ngắn và đồng hồ.
 * - 4 nút điều hướng giữa các state: Thiết bị | Màn hình chính | Biểu đồ | Logs.
 *   Bấm nút -> self.ctx.stateController.updateState(<id state>) (thay state hiện tại,
 *   không chồng thêm breadcrumb). Nút của state đang mở được tô sáng.
 * - Danh sách nút lấy từ settings.navItems: [{"id": "<id state>", "label": "...", "icon": "<material icon>"}].
 */

var DEFAULT_NAV = [
    { id: 'default', label: 'Thiết bị', icon: 'devices' },
    { id: 'main', label: 'Màn hình chính', icon: 'dashboard' },
    { id: 'charts', label: 'Biểu đồ', icon: 'show_chart' },
    { id: 'logs', label: 'Logs', icon: 'receipt_long' }
];

self.onInit = function () {
    var s = self.ctx.settings || {};
    self.navItems = (s.navItems && s.navItems.length) ? s.navItems : DEFAULT_NAV;
    var root = self.ctx.$container[0];

    var nav = self.navItems.map(function (item) {
        return '<button type="button" class="l4-nav-btn" data-state="' + esc(item.id) + '">' +
            '<span class="material-icons">' + esc(item.icon || 'chevron_right') + '</span>' +
            '<span>' + esc(item.label) + '</span></button>';
    }).join('');

    root.innerHTML =
        '<div class="l4-header">' +
        '  <div class="l4-brand">' +
        '    <div class="l4-logo"><span class="material-icons">sensors</span></div>' +
        '    <div class="l4-titles">' +
        '      <div class="l4-title">' + esc(s.title || 'NT532.R12 - Nhóm 10 · Lab 4') + '</div>' +
        '      <div class="l4-subtitle">' + esc(s.subtitle || 'Dashboard IoT: ESP32 (BH1750 + 2 LED) và Raspberry Pi (DHT11) qua MQTT - ThingsBoard CE') + '</div>' +
        '    </div>' +
        '  </div>' +
        '  <nav class="l4-nav">' + nav + '</nav>' +
        '  <div class="l4-clock"><span class="material-icons">schedule</span><span class="l4-clock-text"></span></div>' +
        '</div>';

    self.clickHandler = function (event) {
        var btn = event.target.closest('[data-state]');
        if (btn) {
            goToState(btn.getAttribute('data-state'));
        }
    };
    root.addEventListener('click', self.clickHandler);

    // Tô sáng nút của state hiện tại (và cập nhật khi đổi state)
    markActive(currentStateId());
    var sc = self.ctx.stateController;
    if (sc && typeof sc.stateId === 'function') {
        self.stateSub = sc.stateId().subscribe(function (id) {
            markActive(id);
        });
    }

    updateClock();
    self.clockTimer = setInterval(updateClock, 1000);
};

self.onDestroy = function () {
    if (self.clockTimer) {
        clearInterval(self.clockTimer);
    }
    if (self.stateSub) {
        self.stateSub.unsubscribe();
    }
    if (self.clickHandler) {
        self.ctx.$container[0].removeEventListener('click', self.clickHandler);
    }
};

function currentStateId() {
    var sc = self.ctx.stateController;
    return (sc && sc.getStateId()) || 'default';
}

function goToState(id) {
    var sc = self.ctx.stateController;
    if (!sc || !id || id === currentStateId()) {
        return;
    }
    sc.updateState(id, {}, false);
}

function markActive(id) {
    var buttons = self.ctx.$container[0].querySelectorAll('[data-state]');
    for (var i = 0; i < buttons.length; i++) {
        buttons[i].classList.toggle('active', buttons[i].getAttribute('data-state') === (id || 'default'));
    }
}

function updateClock() {
    var el = self.ctx.$container[0].querySelector('.l4-clock-text');
    if (el) {
        var d = new Date();
        el.textContent = pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds()) +
            '  ' + pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear();
    }
}

function pad(n) {
    return (n < 10 ? '0' : '') + n;
}

function esc(text) {
    return String(text === undefined || text === null ? '' : text)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

self.typeParameters = function () {
    return {
        previewWidth: '100%',
        previewHeight: '110px',
        embedTitlePanel: false
    };
};

