descriptor.controllerScript:
/*
 * LAB 4 - WIDGET "Lab4 - Tổng quan kết nối" (NT532.R12 - Nhóm 10)
 *
 * Widget dạng latest values. Datasource: alias chứa các thiết bị Lab 4 (lọc theo device profile),
 * data key là server attribute "active" (và "lastActivityTime").
 * - "active" do ThingsBoard tự cập nhật: true khi thiết bị gửi dữ liệu / còn giữ kết nối MQTT,
 *   false sau inactivityTimeout (30 s) kể từ lần hoạt động cuối.
 * - Hiện 4 thẻ: tổng số thiết bị, số thiết bị online, số offline, hoạt động gần nhất.
 * - Cập nhật real-time qua WebSocket (subscription của widget), không cần tải lại trang.
 */

self.onInit = function () {
    var root = self.ctx.$container[0];
    root.innerHTML =
        '<div class="l4-sum">' +
        tile('total', 'devices', 'Tổng số thiết bị', 'Thiết bị thuộc 2 device profile Lab 4') +
        tile('online', 'wifi', 'Đang online', 'active = true') +
        tile('offline', 'wifi_off', 'Offline', 'active = false / chưa kết nối') +
        tile('last', 'update', 'Hoạt động gần nhất', '') +
        '</div>';
    self.onDataUpdated();
    // Cập nhật dòng "... giây trước" mỗi giây
    self.timer = setInterval(updateAgo, 1000);
};

self.onDataUpdated = function () {
    var devices = {};
    (self.ctx.datasources || []).forEach(function (ds) {
        if (ds && ds.entityId) {
            devices[ds.entityId] = devices[ds.entityId] || { name: ds.entityName, label: ds.entityLabel };
        }
    });
    (self.ctx.data || []).forEach(function (item) {
        var ds = item.datasource || {};
        if (!ds.entityId) {
            return;
        }
        var dev = devices[ds.entityId] = devices[ds.entityId] || { name: ds.entityName, label: ds.entityLabel };
        var point = item.data && item.data.length ? item.data[item.data.length - 1] : null;
        var value = point ? point[1] : null;
        if (item.dataKey && item.dataKey.name === 'active') {
            dev.active = value === true || String(value).toLowerCase() === 'true';
        } else if (item.dataKey && item.dataKey.name === 'lastActivityTime' && value) {
            dev.lastActivity = Number(value);
        }
    });

    var ids = Object.keys(devices);
    var online = ids.filter(function (id) { return devices[id].active; });
    var last = null;
    ids.forEach(function (id) {
        if (devices[id].lastActivity && (!last || devices[id].lastActivity > last.lastActivity)) {
            last = devices[id];
        }
    });
    self.last = last;

    setText('total', String(ids.length));
    setText('online', String(online.length));
    setText('offline', String(ids.length - online.length));
    setSub('online', online.length ? online.map(function (id) { return devices[id].name; }).join(', ') : 'Không có thiết bị nào online');
    var offlineNames = ids.filter(function (id) { return !devices[id].active; }).map(function (id) { return devices[id].name; });
    setSub('offline', offlineNames.length ? offlineNames.join(', ') : 'Tất cả thiết bị đang online');
    updateAgo();
};

self.onDestroy = function () {
    if (self.timer) {
        clearInterval(self.timer);
    }
};

function updateAgo() {
    var last = self.last;
    if (!last) {
        setText('last', '--');
        setSub('last', 'Chưa có dữ liệu hoạt động');
        return;
    }
    setText('last', ago(last.lastActivity));
    setSub('last', last.name + ' · ' + formatTime(last.lastActivity));
}

function tile(kind, icon, title, sub) {
    return '<div class="l4-tile l4-' + kind + '">' +
        '<div class="l4-tile-icon"><span class="material-icons">' + icon + '</span></div>' +
        '<div class="l4-tile-body">' +
        '<div class="l4-tile-title">' + title + '</div>' +
        '<div class="l4-tile-value" data-v="' + kind + '">--</div>' +
        '<div class="l4-tile-sub" data-s="' + kind + '">' + sub + '</div>' +
        '</div></div>';
}

function setText(kind, text) {
    var el = self.ctx.$container[0].querySelector('[data-v="' + kind + '"]');
    if (el) {
        el.textContent = text;
    }
}

function setSub(kind, text) {
    var el = self.ctx.$container[0].querySelector('[data-s="' + kind + '"]');
    if (el) {
        el.textContent = text;
    }
}

function ago(ts) {
    var sec = Math.max(0, Math.round((Date.now() - ts) / 1000));
    if (sec < 60) {
        return sec + ' giây trước';
    }
    if (sec < 3600) {
        return Math.floor(sec / 60) + ' phút trước';
    }
    if (sec < 86400) {
        return Math.floor(sec / 3600) + ' giờ trước';
    }
    return Math.floor(sec / 86400) + ' ngày trước';
}

function formatTime(ts) {
    var d = new Date(ts);
    function p(n) { return (n < 10 ? '0' : '') + n; }
    return p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds()) + ' ' +
        p(d.getDate()) + '/' + p(d.getMonth() + 1) + '/' + d.getFullYear();
}

self.typeParameters = function () {
    return {
        maxDatasources: 1,
        dataKeysOptional: false,
        singleEntity: false,
        previewWidth: '100%',
        previewHeight: '130px',
        embedTitlePanel: false,
        defaultDataKeysFunction: function () {
            return [
                { name: 'active', label: 'active', type: 'attribute' },
                { name: 'lastActivityTime', label: 'lastActivityTime', type: 'attribute' }
            ];
        }
    };
};

