descriptor.controllerScript:
/*
 * LAB 4 - WIDGET "Lab4 - Thẻ giá trị cảm biến" (NT532.R12 - Nhóm 10)
 *
 * Widget dạng latest values, hiện giá trị MỚI NHẤT của một đại lượng:
 *   tên đại lượng (vd "Nhiệt độ"), tên key (vd "temperature"), giá trị + đơn vị,
 *   thiết bị gửi (tên, rê chuột để xem nhãn), thời điểm nhận và "... giây trước",
 *   trạng thái Online/Offline của thiết bị.
 * Datasource: alias của 1 thiết bị.
 *   - data key thứ nhất (time series): đại lượng cần hiện, vd temperature / humidity / light / rssi
 *   - data key "active" (attribute, tùy chọn): trạng thái kết nối của thiết bị
 * Settings: label, units, decimals, icon (material icon), color, staleSeconds (quá số giây này
 * không có dữ liệu mới thì thẻ chuyển màu xám "dữ liệu cũ").
 */

self.onInit = function () {
    var s = self.ctx.settings || {};
    self.cfg = {
        label: s.label || 'Giá trị',
        units: s.units || '',
        decimals: (s.decimals === undefined || s.decimals === null || s.decimals === '') ? 1 : Number(s.decimals),
        icon: s.icon || 'sensors',
        color: s.color || '#1f5fae',
        staleSeconds: Number(s.staleSeconds) || 30
    };
    var root = self.ctx.$container[0];
    root.innerHTML =
        '<div class="l4-card" style="--l4c:' + esc(self.cfg.color) + '">' +
        '  <div class="l4-card-top">' +
        '    <div class="l4-card-icon" style="background:' + tint(self.cfg.color) + '"><span class="material-icons">' + esc(self.cfg.icon) + '</span></div>' +
        '    <div class="l4-card-names">' +
        '      <div class="l4-card-label">' + esc(self.cfg.label) + '</div>' +
        '      <div class="l4-card-key"></div>' +
        '    </div>' +
        '    <span class="l4-chip"></span>' +
        '  </div>' +
        '  <div class="l4-card-value"><span class="l4-v">--</span><span class="l4-u">' + esc(self.cfg.units) + '</span></div>' +
        '  <div class="l4-card-meta">' +
        '    <div class="l4-device"><span class="material-icons">memory</span><span class="l4-device-text">--</span></div>' +
        '    <div class="l4-time"><span class="material-icons">schedule</span><span class="l4-time-text">Chưa có dữ liệu</span></div>' +
        '  </div>' +
        '</div>';
    self.state = { ts: null, value: null, active: null };
    self.onDataUpdated();
    self.timer = setInterval(renderTime, 1000);
};

self.onDataUpdated = function () {
    var data = self.ctx.data || [];
    var valueItem = null;
    var activeItem = null;
    data.forEach(function (item) {
        var name = item.dataKey && item.dataKey.name;
        if (name === 'active') {
            activeItem = item;
        } else if (!valueItem) {
            valueItem = item;
        }
    });
    var root = self.ctx.$container[0];
    var ds = (valueItem && valueItem.datasource) || (self.ctx.datasources || [])[0] || {};

    var deviceEl = root.querySelector('.l4-device-text');
    deviceEl.textContent = 'Thiết bị: ' + (ds.entityName || '--');
    deviceEl.parentNode.title = ds.entityLabel || ds.entityName || '';
    if (valueItem && valueItem.dataKey) {
        root.querySelector('.l4-card-key').textContent = 'key: ' + valueItem.dataKey.name;
    }

    var point = lastPoint(valueItem);
    if (point && point[1] !== null && point[1] !== undefined && point[1] !== '') {
        self.state.ts = point[0];
        self.state.value = point[1];
    }
    var activePoint = lastPoint(activeItem);
    self.state.active = activePoint ? (activePoint[1] === true || String(activePoint[1]).toLowerCase() === 'true') : null;

    var valueText = '--';
    if (self.state.value !== null) {
        var num = Number(self.state.value);
        valueText = isFinite(num) ? num.toFixed(self.cfg.decimals) : String(self.state.value);
    }
    root.querySelector('.l4-v').textContent = valueText;

    var chip = root.querySelector('.l4-chip');
    chip.className = 'l4-chip';
    if (self.state.active === null) {
        chip.style.display = 'none';
    } else {
        chip.style.display = '';
        chip.classList.add(self.state.active ? 'on' : 'off');
        chip.textContent = self.state.active ? 'Online' : 'Offline';
    }
    renderTime();
};

self.onDestroy = function () {
    if (self.timer) {
        clearInterval(self.timer);
    }
};

function lastPoint(item) {
    if (!item || !item.data || !item.data.length) {
        return null;
    }
    return item.data[item.data.length - 1];
}

function renderTime() {
    var root = self.ctx.$container[0];
    var el = root.querySelector('.l4-time-text');
    var card = root.querySelector('.l4-card');
    if (!el || !card) {
        return;
    }
    if (!self.state.ts) {
        el.textContent = 'Chưa có dữ liệu';
        card.classList.add('stale');
        return;
    }
    var sec = Math.max(0, Math.round((Date.now() - self.state.ts) / 1000));
    el.textContent = 'Cập nhật: ' + formatTime(self.state.ts) + ' · ' + ago(sec);
    card.classList.toggle('stale', sec > self.cfg.staleSeconds);
}

function ago(sec) {
    if (sec < 60) {
        return sec + ' giây trước';
    }
    if (sec < 3600) {
        return Math.floor(sec / 60) + ' phút trước';
    }
    if (sec < 86400) {
        return Math.floor(sec / 3600) + ' giờ trước';
    }
    return Math.floor(sec / 86400) + ' ngày trước';
}

function formatTime(ts) {
    var d = new Date(ts);
    function p(n) { return (n < 10 ? '0' : '') + n; }
    return p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds()) + ' ' +
        p(d.getDate()) + '/' + p(d.getMonth() + 1) + '/' + d.getFullYear();
}

// Màu nền nhạt của icon: màu chính với độ trong suốt 0.12 (chỉ nhận dạng #rrggbb)
function tint(color) {
    var m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(String(color));
    if (!m) {
        return '#eef4fb';
    }
    return 'rgba(' + parseInt(m[1], 16) + ',' + parseInt(m[2], 16) + ',' + parseInt(m[3], 16) + ',0.12)';
}

function esc(text) {
    return String(text === undefined || text === null ? '' : text)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

self.typeParameters = function () {
    return {
        maxDatasources: 1,
        singleEntity: true,
        previewWidth: '300px',
        previewHeight: '200px',
        embedTitlePanel: false,
        defaultDataKeysFunction: function () {
            return [
                { name: 'temperature', label: 'temperature', type: 'timeseries' },
                { name: 'active', label: 'active', type: 'attribute' }
            ];
        }
    };
};

