descriptor.controllerScript:
/*
 * LAB 4 - WIDGET "Lab4 - Nhật ký (Logs)" (NT532.R12 - Nhóm 10)
 *
 * Widget dạng time series. Datasource: alias các thiết bị Lab 4 với các key
 *   temperature, humidity, light, rssi, led1, led2, sysEvent, event
 * ("sysEvent" = sự kiện hệ thống do rule chain của ThingsBoard lưu: CONNECTED / DISCONNECTED /
 *  ACTIVE / INACTIVE, lệnh "RPC setLed1(true)" khi dashboard gửi lệnh và kết quả "RPC DELIVERED" /
 *  "RPC OK: true" / "RPC FAILED: NO_ACTIVE_CONNECTION"; "event" = sự kiện do thiết bị tự gửi:
 *  BOOT / MQTT RECONNECT / DHT11 read error / ...).
 *
 * - Gộp mọi điểm dữ liệu của mọi thiết bị thành bảng dạng "dài", mới nhất ở trên:
 *     Thời gian nhận | ID thiết bị | Tên thiết bị | Tên giá trị | Giá trị
 * - Khoảng thời gian = timewindow của dashboard (realtime hoặc lịch sử, chọn ở thanh công cụ).
 * - Lọc theo thiết bị, tên giá trị, ô tìm kiếm tự do; chọn số dòng mỗi trang; đếm số dòng.
 * - Tải về CÁC DÒNG ĐÃ LỌC: CSV (UTF-8 có BOM để Excel hiện đúng tiếng Việt) hoặc Excel (.xlsx).
 *   ThingsBoard CE 4.3 không cung cấp service xuất Excel cho widget (importExport chỉ có
 *   exportCsv/exportText/exportJSZip), nên file .xlsx được tạo ngay trong trình duyệt
 *   (Office Open XML tối giản, nén ZIP kiểu "store"), không cần thư viện ngoài / Internet.
 * - Mở state Logs từ bảng thiết bị (nút "Xem nhật ký") sẽ lọc sẵn theo thiết bị đó.
 * - settings.compact = true: bản rút gọn (ẩn bộ lọc và nút tải, có nút mở state Logs đầy đủ),
 *   dùng cho khung "Sự kiện gần đây" ở các state khác.
 */

var COLUMNS = ['Thời gian nhận', 'ID thiết bị', 'Tên thiết bị', 'Tên giá trị', 'Giá trị'];

// Mô tả + đơn vị của các key (chỉ để hiển thị, file tải về giữ nguyên tên key và giá trị gốc)
var KEY_INFO = {
    temperature: { text: 'Nhiệt độ', unit: '°C' },
    humidity: { text: 'Độ ẩm', unit: '%' },
    light: { text: 'Ánh sáng', unit: 'lx' },
    rssi: { text: 'Cường độ Wi-Fi', unit: 'dBm' },
    led1: { text: 'Trạng thái LED 1', unit: '' },
    led2: { text: 'Trạng thái LED 2', unit: '' },
    sysEvent: { text: 'Sự kiện hệ thống', unit: '' },
    event: { text: 'Sự kiện thiết bị', unit: '' }
};

self.onInit = function () {
    var s = self.ctx.settings || {};
    self.compact = s.compact === true;
    self.pageSizes = [25, 50, 100, 250];
    self.filter = {
        device: 'all',
        key: 'all',
        text: '',
        page: 0,
        pageSize: Number(s.defaultPageSize) || 50,
        sortAsc: false
    };
    self.rows = [];
    self.filtered = [];
    self.signature = '';
    self.loading = true;      // chưa nhận dữ liệu lần đầu từ subscription

    // Mở từ bảng thiết bị ("Xem nhật ký") -> lọc sẵn theo thiết bị trong state params
    try {
        var params = self.ctx.stateController && self.ctx.stateController.getStateParams();
        if (params && params.entityId && params.entityId.id) {
            self.filter.device = params.entityId.id;
        }
    } catch (e) {
        // không có state params
    }

    var root = self.ctx.$container[0];
    root.innerHTML =
        '<div class="l4-logs' + (self.compact ? ' l4-compact' : '') + '">' +
        '  <div class="l4-bar">' +
        '    <div class="l4-heading">' +
        '      <span class="material-icons">receipt_long</span>' +
        '      <div><div class="l4-h-title">' + esc(s.title || 'Nhật ký hệ thống & dữ liệu cảm biến') + '</div>' +
        '      <div class="l4-h-range"></div></div>' +
        '    </div>' +
        '    <div class="l4-actions">' +
        '      <button type="button" class="l4-btn l4-btn-flat l4-open" data-act="open-logs" title="Mở trang Logs đầy đủ (lọc, tải CSV/Excel)"><span class="material-icons">open_in_new</span>Xem tất cả</button>' +
        '      <button type="button" class="l4-btn" data-act="csv" title="Tải các dòng đã lọc dạng CSV (UTF-8)"><span class="material-icons">download</span>CSV</button>' +
        '      <button type="button" class="l4-btn l4-btn-green" data-act="xlsx" title="Tải các dòng đã lọc dạng Excel (.xlsx)"><span class="material-icons">grid_on</span>Excel</button>' +
        '    </div>' +
        '  </div>' +
        '  <div class="l4-filters">' +
        '    <label>Thiết bị<select data-f="device"></select></label>' +
        '    <label>Tên giá trị<select data-f="key"></select></label>' +
        '    <label class="l4-grow">Tìm kiếm<input type="search" data-f="text" placeholder="Nhập từ khóa: tên, giá trị, thời gian, ID..."></label>' +
        '    <label>Số dòng/trang<select data-f="pageSize">' +
        self.pageSizes.map(function (n) { return '<option value="' + n + '">' + n + '</option>'; }).join('') +
        '    </select></label>' +
        '    <button type="button" class="l4-btn l4-btn-flat" data-act="reset" title="Bỏ mọi bộ lọc"><span class="material-icons">filter_alt_off</span>Xóa lọc</button>' +
        '  </div>' +
        '  <div class="l4-count"></div>' +
        '  <div class="l4-table-wrap"><table class="l4-table">' +
        '    <thead><tr>' +
        '      <th class="l4-sort" data-act="sort">' + COLUMNS[0] + ' <span class="material-icons l4-sort-icon"></span></th>' +
        '      <th>' + COLUMNS[1] + '</th><th>' + COLUMNS[2] + '</th><th>' + COLUMNS[3] + '</th><th>' + COLUMNS[4] + '</th>' +
        '    </tr></thead><tbody></tbody></table>' +
        '    <div class="l4-empty">Không có dòng nào khớp bộ lọc trong khoảng thời gian đã chọn.</div>' +
        '  </div>' +
        '  <div class="l4-pager">' +
        '    <button type="button" class="l4-icon-btn" data-act="first" title="Trang đầu"><span class="material-icons">first_page</span></button>' +
        '    <button type="button" class="l4-icon-btn" data-act="prev" title="Trang trước"><span class="material-icons">chevron_left</span></button>' +
        '    <span class="l4-page"></span>' +
        '    <button type="button" class="l4-icon-btn" data-act="next" title="Trang sau"><span class="material-icons">chevron_right</span></button>' +
        '    <button type="button" class="l4-icon-btn" data-act="last" title="Trang cuối"><span class="material-icons">last_page</span></button>' +
        '  </div>' +
        '</div>';

    self.el = {
        device: root.querySelector('[data-f="device"]'),
        key: root.querySelector('[data-f="key"]'),
        text: root.querySelector('[data-f="text"]'),
        pageSize: root.querySelector('[data-f="pageSize"]'),
        range: root.querySelector('.l4-h-range'),
        count: root.querySelector('.l4-count'),
        tbody: root.querySelector('tbody'),
        empty: root.querySelector('.l4-empty'),
        page: root.querySelector('.l4-page'),
        sortIcon: root.querySelector('.l4-sort-icon'),
        wrap: root.querySelector('.l4-table-wrap')
    };
    if (self.pageSizes.indexOf(self.filter.pageSize) < 0) {
        self.filter.pageSize = 50;
    }
    self.el.pageSize.value = String(self.filter.pageSize);

    self.handlers = {
        change: function (event) {
            var f = event.target.getAttribute('data-f');
            if (!f) {
                return;
            }
            self.filter[f] = f === 'pageSize' ? Number(event.target.value) : event.target.value;
            self.filter.page = 0;
            applyFilter();
        },
        input: function (event) {
            if (event.target.getAttribute('data-f') !== 'text') {
                return;
            }
            clearTimeout(self.textTimer);
            self.textTimer = setTimeout(function () {
                self.filter.text = self.el.text.value;
                self.filter.page = 0;
                applyFilter();
            }, 200);
        },
        click: function (event) {
            var target = event.target.closest('[data-act]');
            if (!target) {
                return;
            }
            var act = target.getAttribute('data-act');
            var pages = pageCount();
            if (act === 'open-logs') {
                if (self.ctx.stateController) {
                    self.ctx.stateController.updateState(s.logsStateId || 'logs', {}, false);
                }
            } else if (act === 'csv') {
                downloadCsv();
            } else if (act === 'xlsx') {
                downloadXlsx();
            } else if (act === 'reset') {
                self.filter.device = 'all';
                self.filter.key = 'all';
                self.filter.text = '';
                self.filter.page = 0;
                self.el.text.value = '';
                applyFilter();
            } else if (act === 'sort') {
                self.filter.sortAsc = !self.filter.sortAsc;
                self.filter.page = 0;
                applyFilter();
            } else if (act === 'first') {
                gotoPage(0);
            } else if (act === 'prev') {
                gotoPage(self.filter.page - 1);
            } else if (act === 'next') {
                gotoPage(self.filter.page + 1);
            } else if (act === 'last') {
                gotoPage(pages - 1);
            }
        }
    };
    root.addEventListener('change', self.handlers.change);
    root.addEventListener('input', self.handlers.input);
    root.addEventListener('click', self.handlers.click);

    collectRows();
    // Phòng trường hợp không nhận được lần cập nhật nào (khoảng thời gian trống)
    self.loadingTimer = setTimeout(function () {
        if (self.loading) {
            finishLoading();
            collectRows();
        }
    }, 5000);
};

self.onDataUpdated = function () {
    var sub = self.ctx.defaultSubscription;
    if (self.loading && !(sub && sub.loadingData)) {
        finishLoading();
    }
    collectRows();
};

// Hết trạng thái "đang tải": vẽ lại kể cả khi khoảng thời gian không có dòng nào
function finishLoading() {
    self.loading = false;
    self.signature = null;
    clearTimeout(self.loadingTimer);
}

// Gom dữ liệu thành các dòng; bỏ qua nếu không có điểm mới (tránh vẽ lại thừa)
function collectRows() {
    var rows = [];
    var sig = [];
    (self.ctx.data || []).forEach(function (item) {
        var ds = item.datasource || {};
        var key = (item.dataKey && item.dataKey.name) || '';
        var points = item.data || [];
        sig.push((ds.entityId || '') + key + ':' + points.length + ':' + (points.length ? points[points.length - 1][0] : 0));
        for (var i = 0; i < points.length; i++) {
            var p = points[i];
            if (!p || p[1] === null || p[1] === undefined || p[1] === '') {
                continue;
            }
            rows.push({
                ts: Number(p[0]),
                deviceId: ds.entityId || '',
                deviceName: ds.entityName || ds.name || '',
                key: key,
                value: p[1]
            });
        }
    });
    var signature = sig.join('|');
    updateRange();
    if (signature === self.signature) {
        return;
    }
    self.signature = signature;
    rows.forEach(function (r) {
        r.time = formatTime(r.ts);
        r.valueText = valueToText(r.value);
        r.search = (r.time + ' ' + formatIso(r.ts) + ' ' + r.deviceId + ' ' + r.deviceName + ' ' + r.key + ' ' +
            (KEY_INFO[r.key] ? KEY_INFO[r.key].text : '') + ' ' + r.valueText).toLowerCase();
    });
    self.rows = rows;
    updateFilterOptions();
    applyFilter();
}

self.onResize = function () {
};

self.onDestroy = function () {
    var root = self.ctx.$container[0];
    if (self.handlers) {
        root.removeEventListener('change', self.handlers.change);
        root.removeEventListener('input', self.handlers.input);
        root.removeEventListener('click', self.handlers.click);
    }
    clearTimeout(self.textTimer);
    clearTimeout(self.loadingTimer);
};

// ---------------------------------------------------------------------------
// Lọc, sắp xếp, phân trang
// ---------------------------------------------------------------------------
function updateFilterOptions() {
    var devices = {};
    (self.ctx.datasources || []).forEach(function (ds) {
        if (ds && ds.entityId) {
            devices[ds.entityId] = ds.entityName || ds.entityId;
        }
    });
    self.rows.forEach(function (r) {
        if (r.deviceId && !devices[r.deviceId]) {
            devices[r.deviceId] = r.deviceName;
        }
    });
    var keys = {};
    (self.ctx.data || []).forEach(function (item) {
        if (item.dataKey && item.dataKey.name) {
            keys[item.dataKey.name] = true;
        }
    });
    var deviceOptions = [['all', 'Tất cả thiết bị']].concat(Object.keys(devices).sort(function (a, b) {
        return devices[a].localeCompare(devices[b]);
    }).map(function (id) { return [id, devices[id]]; }));
    var keyOptions = [['all', 'Tất cả giá trị']].concat(Object.keys(keys).map(function (k) {
        return [k, KEY_INFO[k] ? k + ' - ' + KEY_INFO[k].text : k];
    }));
    setOptions(self.el.device, deviceOptions, 'device');
    setOptions(self.el.key, keyOptions, 'key');
}

function setOptions(select, options, field) {
    var html = options.map(function (o) {
        return '<option value="' + esc(o[0]) + '">' + esc(o[1]) + '</option>';
    }).join('');
    if (select.getAttribute('data-html') !== html) {
        select.innerHTML = html;
        select.setAttribute('data-html', html);
    }
    var exists = options.some(function (o) { return o[0] === self.filter[field]; });
    if (!exists) {
        self.filter[field] = 'all';
    }
    select.value = self.filter[field];
}

function applyFilter() {
    var f = self.filter;
    var words = f.text.toLowerCase().split(/\s+/).filter(function (w) { return w; });
    self.filtered = self.rows.filter(function (r) {
        if (f.device !== 'all' && r.deviceId !== f.device) {
            return false;
        }
        if (f.key !== 'all' && r.key !== f.key) {
            return false;
        }
        for (var i = 0; i < words.length; i++) {
            if (r.search.indexOf(words[i]) < 0) {
                return false;
            }
        }
        return true;
    });
    var dir = f.sortAsc ? 1 : -1;
    self.filtered.sort(function (a, b) {
        return (a.ts - b.ts) * dir || a.deviceName.localeCompare(b.deviceName) || a.key.localeCompare(b.key);
    });
    self.el.device.value = f.device;
    self.el.key.value = f.key;
    render();
}

function pageCount() {
    return Math.max(1, Math.ceil(self.filtered.length / self.filter.pageSize));
}

function gotoPage(page) {
    self.filter.page = Math.min(Math.max(0, page), pageCount() - 1);
    render();
    self.el.wrap.scrollTop = 0;
}

function render() {
    var f = self.filter;
    var total = self.filtered.length;
    if (f.page > pageCount() - 1) {
        f.page = pageCount() - 1;
    }
    var start = f.page * f.pageSize;
    var pageRows = self.filtered.slice(start, start + f.pageSize);
    self.el.tbody.innerHTML = pageRows.map(rowHtml).join('');
    self.el.empty.style.display = total ? 'none' : 'block';
    self.el.empty.textContent = self.loading ? 'Đang tải dữ liệu...'
        : 'Không có dòng nào khớp bộ lọc trong khoảng thời gian đã chọn.';
    self.el.count.innerHTML = self.loading ? 'Đang tải dữ liệu...' : total
        ? 'Hiển thị <b>' + fmtInt(start + 1) + '–' + fmtInt(start + pageRows.length) + '</b> / <b>' + fmtInt(total) +
          '</b> dòng đã lọc' + (total !== self.rows.length ? ' (tổng ' + fmtInt(self.rows.length) + ' dòng trong khoảng thời gian)' : '')
        : 'Không có dòng nào (tổng ' + fmtInt(self.rows.length) + ' dòng trong khoảng thời gian)';
    self.el.page.textContent = 'Trang ' + (f.page + 1) + ' / ' + pageCount();
    self.el.sortIcon.textContent = f.sortAsc ? 'arrow_upward' : 'arrow_downward';
}

function rowHtml(r) {
    var info = KEY_INFO[r.key];
    var valueCell;
    if (r.key === 'event' || r.key === 'sysEvent') {
        valueCell = '<span class="l4-ev ' + eventClass(r.valueText) + '">' + esc(r.valueText) + '</span>';
    } else if (r.key === 'led1' || r.key === 'led2') {
        var on = r.valueText === 'true';
        valueCell = '<span class="l4-led ' + (on ? 'on' : 'off') + '">' + esc(r.valueText) + '</span>' +
            '<span class="l4-unit">' + (on ? 'BẬT' : 'TẮT') + '</span>';
    } else {
        valueCell = '<b>' + esc(r.valueText) + '</b>' + (info && info.unit ? '<span class="l4-unit">' + esc(info.unit) + '</span>' : '');
    }
    return '<tr>' +
        '<td class="l4-nowrap">' + esc(r.time) + '</td>' +
        '<td class="l4-id" title="' + esc(r.deviceId) + '">' + esc(r.deviceId) + '</td>' +
        '<td class="l4-nowrap">' + esc(r.deviceName) + '</td>' +
        '<td class="l4-nowrap"><code>' + esc(r.key) + '</code>' + (info ? '<span class="l4-unit">' + esc(info.text) + '</span>' : '') + '</td>' +
        '<td>' + valueCell + '</td>' +
        '</tr>';
}

function eventClass(text) {
    var t = String(text).toUpperCase();
    if (t.indexOf('RPC FAILED') === 0) {
        return 'warn';
    }
    if (t.indexOf('RPC') === 0) {
        return 'rpc';
    }
    if (t === 'CONNECTED' || t === 'ACTIVE' || t === 'BOOT' || t.indexOf('RECOVERED') >= 0 || t.indexOf('RECONNECT') >= 0) {
        return 'ok';
    }
    if (t === 'DISCONNECTED' || t === 'INACTIVE' || t === 'SHUTDOWN') {
        return 'bad';
    }
    if (t.indexOf('ERROR') >= 0) {
        return 'warn';
    }
    return '';
}

function updateRange() {
    var text = 'Khoảng thời gian: theo bộ chọn thời gian của dashboard';
    try {
        var sub = self.ctx.defaultSubscription;
        var tw = sub && sub.subscriptionTimewindow;
        if (tw && tw.realtimeWindowMs) {
            text = 'Realtime: ' + durationText(tw.realtimeWindowMs) + ' gần nhất (cập nhật liên tục)';
        } else if (tw && tw.fixedWindow) {
            text = 'Lịch sử: ' + formatTime(tw.fixedWindow.startTimeMs) + ' → ' + formatTime(tw.fixedWindow.endTimeMs);
        }
    } catch (e) {
        // giữ mô tả mặc định
    }
    self.rangeText = text;
    if (self.el && self.el.range) {
        self.el.range.textContent = self.compact ? text : text + ' · đổi ở biểu tượng đồng hồ trên thanh công cụ';
    }
}

function durationText(ms) {
    var min = Math.round(ms / 60000);
    if (min < 60) {
        return min + ' phút';
    }
    if (min % 1440 === 0) {
        return (min / 1440) + ' ngày';
    }
    if (min % 60 === 0) {
        return (min / 60) + ' giờ';
    }
    return min + ' phút';
}

// ---------------------------------------------------------------------------
// Tải về: CSV và Excel (.xlsx) của CÁC DÒNG ĐÃ LỌC
// ---------------------------------------------------------------------------
function exportRows() {
    return self.filtered.map(function (r) {
        return [formatIso(r.ts), r.deviceId, r.deviceName, r.key, r.valueText];
    });
}

function fileName(ext) {
    var d = new Date();
    return 'lab4_logs_' + d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate()) + '_' +
        p2(d.getHours()) + p2(d.getMinutes()) + p2(d.getSeconds()) + '.' + ext;
}

function downloadCsv() {
    var lines = [COLUMNS].concat(exportRows()).map(function (cols) {
        return cols.map(csvCell).join(',');
    });
    // BOM UTF-8 (﻿) để Excel nhận đúng tiếng Việt; xuống dòng CRLF theo RFC 4180
    var blob = new Blob(['﻿' + lines.join('\r\n') + '\r\n'], { type: 'text/csv;charset=utf-8' });
    saveBlob(blob, fileName('csv'));
    toast('Đã tải ' + fmtInt(self.filtered.length) + ' dòng (CSV)');
}

function csvCell(value) {
    var s = String(value === null || value === undefined ? '' : value);
    // Chặn CSV injection khi mở bằng Excel (giá trị bắt đầu bằng = + - @ mà không phải số)
    if (/^[=+\-@]/.test(s) && !isFinite(Number(s))) {
        s = "'" + s;
    }
    if (/[",\r\n]/.test(s)) {
        s = '"' + s.replace(/"/g, '""') + '"';
    }
    return s;
}

