var XML_HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
var NS_MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
var NS_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';

function strCell(ref, text, style) {
    return '<c r="' + ref + '" t="inlineStr"' + (style ? ' s="' + style + '"' : '') + '><is><t xml:space="preserve">' +
        xmlEsc(text) + '</t></is></c>';
}

function cellRef(col, row) {
    return String.fromCharCode(65 + col) + row;
}

// Số ngày kiểu Excel (1900 date system) theo giờ địa phương của trình duyệt
function excelDate(ts) {
    var offset = new Date(ts).getTimezoneOffset() * 60000;
    return ((ts - offset) / 86400000 + 25569).toFixed(8);
}

function xmlEsc(text) {
    return String(text === null || text === undefined ? '' : text)
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F￾￿]/g, '')
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ZIP không nén (method 0 = store): đủ cho file .xlsx, Excel / LibreOffice mở bình thường
function zipStore(files) {
    var encoder = new TextEncoder();
    var chunks = [];
    var central = [];
    var offset = 0;
    var now = new Date();
    var dosTime = (now.getHours() << 11) | (now.getMinutes() << 5) | Math.floor(now.getSeconds() / 2);
    var dosDate = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();
    files.forEach(function (file) {
        var name = encoder.encode(file[0]);
        var data = encoder.encode(file[1]);
        var crc = crc32(data);
        var local = new DataView(new ArrayBuffer(30));
        local.setUint32(0, 0x04034b50, true);
        local.setUint16(4, 20, true);
        local.setUint16(6, 0x0800, true);     // tên file UTF-8
        local.setUint16(8, 0, true);          // store
        local.setUint16(10, dosTime, true);
        local.setUint16(12, dosDate, true);
        local.setUint32(14, crc, true);
        local.setUint32(18, data.length, true);
        local.setUint32(22, data.length, true);
        local.setUint16(26, name.length, true);
        local.setUint16(28, 0, true);
        chunks.push(new Uint8Array(local.buffer), name, data);

        var entry = new DataView(new ArrayBuffer(46));
        entry.setUint32(0, 0x02014b50, true);
        entry.setUint16(4, 20, true);
        entry.setUint16(6, 20, true);
        entry.setUint16(8, 0x0800, true);
        entry.setUint16(10, 0, true);
        entry.setUint16(12, dosTime, true);
        entry.setUint16(14, dosDate, true);
        entry.setUint32(16, crc, true);
        entry.setUint32(20, data.length, true);
        entry.setUint32(24, data.length, true);
        entry.setUint16(28, name.length, true);
        entry.setUint16(30, 0, true);
        entry.setUint16(32, 0, true);
        entry.setUint16(34, 0, true);
        entry.setUint16(36, 0, true);
        entry.setUint32(38, 0, true);
        entry.setUint32(42, offset, true);
        central.push(new Uint8Array(entry.buffer), name);
        offset += 30 + name.length + data.length;
    });
    var centralSize = central.reduce(function (sum, c) { return sum + c.length; }, 0);
    var end = new DataView(new ArrayBuffer(22));
    end.setUint32(0, 0x06054b50, true);
    end.setUint16(8, files.length, true);
    end.setUint16(10, files.length, true);
    end.setUint32(12, centralSize, true);
    end.setUint32(16, offset, true);
    return new Blob(chunks.concat(central, [new Uint8Array(end.buffer)]));
}

var CRC_TABLE = null;
function crc32(bytes) {
    if (!CRC_TABLE) {
        CRC_TABLE = new Uint32Array(256);
        for (var n = 0; n < 256; n++) {
            var c = n;
            for (var k = 0; k < 8; k++) {
                c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
            }
            CRC_TABLE[n] = c >>> 0;
        }
    }
    var crc = 0xFFFFFFFF;
    for (var i = 0; i < bytes.length; i++) {
        crc = CRC_TABLE[(crc ^ bytes[i]) & 0xFF] ^ (crc >>> 8);
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function saveBlob(blob, name) {
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = name;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () {
        URL.revokeObjectURL(url);
        a.remove();
    }, 2000);
}

function toast(message) {
    try {
        self.ctx.showSuccessToast(message, 2500, 'bottom', 'right');
    } catch (e) {
        // không có toast cũng không sao
    }
}

// ---------------------------------------------------------------------------
// Định dạng
// ---------------------------------------------------------------------------
function valueToText(value) {
    if (value === true || value === false) {
        return String(value);
    }
    if (typeof value === 'object') {
        return JSON.stringify(value);
    }
    return String(value);
}

function p2(n) {
    return (n < 10 ? '0' : '') + n;
}

function formatTime(ts) {
    var d = new Date(ts);
    return p2(d.getDate()) + '/' + p2(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' +
        p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds());
}

function formatIso(ts) {
    var d = new Date(ts);
    return d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate()) + ' ' +
        p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds());
}

function fmtInt(n) {
    return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

function esc(text) {
    return String(text === undefined || text === null ? '' : text)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

self.typeParameters = function () {
    return {
        maxDatasources: 4,
        dataKeysOptional: false,
        ignoreDataUpdateOnIntervalTick: true,
        previewWidth: '100%',
        previewHeight: '500px',
        embedTitlePanel: false,
        defaultDataKeysFunction: function () {
            return ['temperature', 'humidity', 'light', 'rssi', 'led1', 'led2', 'sysEvent', 'event'].map(function (k) {
                return { name: k, label: k, type: 'timeseries' };
            });
        }
    };
};
